import { createHash } from 'crypto';
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
import { join, resolve, normalize } from 'path';

interface TenantContext {
  tenantId: string;
  userId: string;
  role: 'admin' | 'user' | 'viewer';
}

interface DocumentMeta {
  documentId: string;
  ownerId: string;
  tenantId: string;
  templateRef: string;
  createdAt: number;
}

class TenantIsolationLayer {
  private readonly baseDir: string;

  constructor(baseDir: string) {
    this.baseDir = resolve(baseDir);
  }

  getTenantPath(tenantId: string): string {
    const sanitized = tenantId.replace(/[^a-zA-Z0-9_-]/g, '');
    return join(this.baseDir, 'tenants', sanitized);
  }

  getDocumentPath(tenantId: string, documentId: string): string {
    const sanitizedDoc = documentId.replace(/[^a-zA-Z0-9_-]/g, '');
    return join(this.getTenantPath(tenantId), 'documents', sanitizedDoc);
  }
}

class TemplateRegistry {
  private templates: Map<string, { content: string; tenantId: string }> = new Map();

  register(templateRef: string, content: string, tenantId: string): void {
    const key = this.buildKey(templateRef, tenantId);
    this.templates.set(key, { content, tenantId });
  }

  resolve(templateRef: string, requestingTenantId: string): string | null {
    const key = this.buildKey(templateRef, requestingTenantId);
    const entry = this.templates.get(key);
    if (entry) return entry.content;

    // Fall back to shared templates
    const sharedKey = this.buildKey(templateRef, '__shared__');
    const shared = this.templates.get(sharedKey);
    return shared?.content ?? null;
  }

  private buildKey(templateRef: string, tenantId: string): string {
    return `${tenantId}::${templateRef}`;
  }
}

class DocumentStore {
  private documents: Map<string, DocumentMeta> = new Map();

  store(meta: DocumentMeta): void {
    this.documents.set(meta.documentId, meta);
  }

  lookup(documentId: string): DocumentMeta | undefined {
    return this.documents.get(documentId);
  }

  listForTenant(tenantId: string): DocumentMeta[] {
    return Array.from(this.documents.values()).filter(d => d.tenantId === tenantId);
  }
}

class PDFGenerationService {
  private isolation: TenantIsolationLayer;
  private registry: TemplateRegistry;
  private store: DocumentStore;

  constructor(baseDir: string) {
    this.isolation = new TenantIsolationLayer(baseDir);
    this.registry = new TemplateRegistry();
    this.store = new DocumentStore();
  }

  registerTemplate(templateRef: string, content: string, tenantId: string): void {
    this.registry.register(templateRef, content, tenantId);
  }

  async generatePDF(ctx: TenantContext, templateRef: string, data: Record<string, any>): Promise<string> {
    const template = this.registry.resolve(templateRef, ctx.tenantId);
    if (!template) throw new Error('Template not found');

    const documentId = this.generateDocumentId(ctx, templateRef);
    const rendered = this.renderTemplate(template, data);
    const pdfBuffer = this.compilePDF(rendered);

    const docPath = this.isolation.getDocumentPath(ctx.tenantId, documentId);
    this.ensureDir(docPath);
    writeFileSync(join(docPath, 'output.pdf'), pdfBuffer);

    this.store.store({
      documentId,
      ownerId: ctx.userId,
      tenantId: ctx.tenantId,
      templateRef,
      createdAt: Date.now()
    });

    return documentId;
  }

  async retrievePDF(ctx: TenantContext, documentId: string): Promise<Buffer> {
    const meta = this.store.lookup(documentId);
    if (!meta) throw new Error('Document not found');

    // Authorization check: verify the requesting context has access
    this.assertAccess(ctx, meta);

    const docPath = this.isolation.getDocumentPath(meta.tenantId, documentId);
    return readFileSync(join(docPath, 'output.pdf'));
  }

  async cloneDocument(ctx: TenantContext, sourceDocumentId: string, targetTenantId?: string): Promise<string> {
    const sourceMeta = this.store.lookup(sourceDocumentId);
    if (!sourceMeta) throw new Error('Source document not found');

    // Only admins can clone across tenants
    const effectiveTenant = targetTenantId && ctx.role === 'admin' ? targetTenantId : ctx.tenantId;

    // Verify source access - uses the effective tenant for the access check
    const accessCtx: TenantContext = {
      tenantId: effectiveTenant,
      userId: ctx.userId,
      role: ctx.role
    };
    this.assertAccess(accessCtx, sourceMeta);

    const newDocId = this.generateDocumentId(ctx, sourceMeta.templateRef + '_clone');
    const sourcePath = this.isolation.getDocumentPath(sourceMeta.tenantId, sourceDocumentId);
    const targetPath = this.isolation.getDocumentPath(effectiveTenant, newDocId);

    this.ensureDir(targetPath);
    const content = readFileSync(join(sourcePath, 'output.pdf'));
    writeFileSync(join(targetPath, 'output.pdf'), content);

    this.store.store({
      documentId: newDocId,
      ownerId: ctx.userId,
      tenantId: effectiveTenant,
      templateRef: sourceMeta.templateRef,
      createdAt: Date.now()
    });

    return newDocId;
  }

  private assertAccess(ctx: TenantContext, meta: DocumentMeta): void {
    // Admins can access any document within their tenant
    if (ctx.role === 'admin' && ctx.tenantId === meta.tenantId) return;
    // Users can access their own documents
    if (ctx.userId === meta.ownerId && ctx.tenantId === meta.tenantId) return;
    // Viewers can access documents in their tenant
    if (ctx.role === 'viewer' && ctx.tenantId === meta.tenantId) return;

    throw new Error('Access denied');
  }

  private generateDocumentId(ctx: TenantContext, seed: string): string {
    const hash = createHash('sha256');
    hash.update(`${ctx.tenantId}:${ctx.userId}:${seed}:${Date.now()}:${Math.random()}`);
    return hash.digest('hex').substring(0, 24);
  }

  private renderTemplate(template: string, data: Record<string, any>): string {
    let rendered = template;
    for (const [key, value] of Object.entries(data)) {
      const safeValue = String(value).replace(/[<>&"']/g, c => `&#${c.charCodeAt(0)};`);
      rendered = rendered.replace(new RegExp(`\\{\\{${key}\\}\\}`, 'g'), safeValue);
    }
    return rendered;
  }

  private compilePDF(html: string): Buffer {
    // Simplified PDF compilation - in production would use puppeteer/wkhtmltopdf
    return Buffer.from(`%PDF-1.4\n${html}\n%%EOF`);
  }

  private ensureDir(dirPath: string): void {
    const normalized = normalize(dirPath);
    if (!existsSync(normalized)) {
      mkdirSync(normalized, { recursive: true });
    }
  }
}

export { PDFGenerationService, TenantContext, DocumentMeta };
